import React, { useState } from "react";
import { motion } from "framer-motion";
import { Star } from "lucide-react";

const Feedback = () => {
  const [rating, setRating] = useState(0);
  const [comment, setComment] = useState("");

  const handleSubmit = (e) => {
    e.preventDefault();
    alert(`Feedback submitted with ${rating} stars and comment: ${comment}`);
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-background to-gray-100 p-8">
      <motion.div
        className="bg-white shadow-xl rounded-xl p-10 w-full max-w-lg border border-gray-200"
        initial={{ opacity: 0, y: 40 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        <h2 className="text-3xl font-serif text-center text-primary mb-6">
          Share Your Experience
        </h2>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="flex justify-center space-x-3">
            {[1, 2, 3, 4, 5].map((star) => (
              <Star
                key={star}
                onClick={() => setRating(star)}
                className={`w-8 h-8 cursor-pointer transition ${
                  star <= rating ? "text-secondary" : "text-gray-400"
                }`}
              />
            ))}
          </div>

          <div>
            <label className="block text-gray-600 mb-2">Comments</label>
            <textarea
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              rows="4"
              placeholder="Share your feedback..."
              className="w-full border border-gray-300 rounded-md p-3 outline-none focus:ring-2 focus:ring-secondary"
            ></textarea>
          </div>

          <button
            type="submit"
            className="w-full bg-secondary text-white py-3 rounded-md hover:bg-primary transition font-medium shadow-md"
          >
            Submit Feedback
          </button>
        </form>
      </motion.div>
    </div>
  );
};

export default Feedback;
